import{_ as t,c as d,a as r,aS as o}from"./chunks/framework.BB9D2qGO.js";const u=JSON.parse('{"title":"中国地理","description":"","frontmatter":{},"headers":[],"relativePath":"note/knowledge/09-中国地理.md","filePath":"note/knowledge/09-中国地理.md","lastUpdated":1750689348000}'),n={name:"note/knowledge/09-中国地理.md"},s=o('<h1 id="中国地理" tabindex="-1">中国地理 <a class="header-anchor" href="#中国地理" aria-label="Permalink to &quot;中国地理&quot;">​</a></h1><h2 id="民族" tabindex="-1">民族 <a class="header-anchor" href="#民族" aria-label="Permalink to &quot;民族&quot;">​</a></h2><h1 id="中国各民族人口及分布表-前20位" tabindex="-1">中国各民族人口及分布表（前20位） <a class="header-anchor" href="#中国各民族人口及分布表-前20位" aria-label="Permalink to &quot;中国各民族人口及分布表（前20位）&quot;">​</a></h1><table tabindex="0"><thead><tr><th>民族</th><th>人口（万）</th><th>主要分布地区</th><th>备注</th></tr></thead><tbody><tr><td><strong>汉族</strong></td><td>122,084</td><td>全国各省</td><td>占全国人口91.59%，世界第一大民族</td></tr><tr><td><strong>壮族</strong></td><td>1,693</td><td>广西、云南、广东</td><td>最大少数民族，李宁为代表人物</td></tr><tr><td><strong>回族</strong></td><td>1,059</td><td>宁夏、甘肃、新疆</td><td>分布最广的少数民族，通用汉语</td></tr><tr><td><strong>满族</strong></td><td>1,039</td><td>辽宁、河北、黑龙江</td><td>曾建立清朝，现多使用汉语</td></tr><tr><td><strong>维吾尔族</strong></td><td>1,007</td><td>新疆</td><td>占新疆人口44.96%，以十二木卡姆艺术闻名</td></tr><tr><td><strong>苗族</strong></td><td>943</td><td>贵州、湖南、云南</td><td>蜡染技艺被列为国家级非遗</td></tr><tr><td><strong>彝族</strong></td><td>871</td><td>四川凉山、云南</td><td>火把节为重要文化符号</td></tr><tr><td><strong>土家族</strong></td><td>835</td><td>湖南、湖北、重庆</td><td>无文字民族，摆手舞为特色</td></tr><tr><td><strong>藏族</strong></td><td>628</td><td>西藏、青海、四川</td><td>高原文化代表，藏传佛教影响深远</td></tr><tr><td><strong>蒙古族</strong></td><td>598</td><td>内蒙古、辽宁、新疆</td><td>那达慕大会为标志性活动</td></tr><tr><td><strong>侗族</strong></td><td>288</td><td>贵州、湖南、广西</td><td>鼓楼和风雨桥建筑独具特色</td></tr><tr><td><strong>布依族</strong></td><td>287</td><td>贵州</td><td>以蜡染和石板房著称</td></tr><tr><td><strong>瑶族</strong></td><td>280</td><td>广西、湖南、云南</td><td>盘王节为重要节日，长鼓舞为非遗</td></tr><tr><td><strong>白族</strong></td><td>193</td><td>云南大理</td><td>三道茶文化、扎染工艺闻名</td></tr><tr><td><strong>朝鲜族</strong></td><td>183</td><td>吉林延边、黑龙江</td><td>中国唯一使用朝鲜语文的民族，崔健为代表人物</td></tr><tr><td><strong>哈尼族</strong></td><td>166</td><td>云南红河</td><td>梯田文化入选世界遗产</td></tr><tr><td><strong>哈萨克族</strong></td><td>146</td><td>新疆伊犁、甘肃阿克塞</td><td>游牧文化代表，冬不拉琴为特色</td></tr><tr><td><strong>黎族</strong></td><td>146</td><td>海南</td><td>船型屋和黎锦技艺被列为非遗</td></tr><tr><td><strong>傣族</strong></td><td>126</td><td>云南西双版纳</td><td>泼水节为国家级非物质文化遗产</td></tr><tr><td><strong>畲族</strong></td><td>71</td><td>福建、浙江</td><td>凤凰装和畲族民歌为文化标识</td></tr></tbody></table><h3 id="补充说明" tabindex="-1">补充说明 <a class="header-anchor" href="#补充说明" aria-label="Permalink to &quot;补充说明&quot;">​</a></h3><ol><li><strong>总览</strong>：中国共有56个民族，汉族占91.59%，少数民族占8.41%（2020年数据）；</li><li><strong>最少民族</strong>：塔塔尔族仅3,500人（新疆）、珞巴族4,200人（西藏）；</li><li><strong>分布特点</strong>：大杂居小聚居，云南有25个世居民族（全国最多）；</li><li><strong>特别群体</strong>：俄罗斯族（白种人，新疆北部）、塔吉克族（帕米尔高原守护者）；</li><li><strong>数据来源</strong>：主要依据2020年人口普查及地方政府统计公报。</li></ol><p>完整55个少数民族名单及其他民族详细信息，可查阅《中国统计年鉴》或国家民族事务委员会官网。</p><h2 id="中国省级行政区划表" tabindex="-1">中国省级行政区划表 <a class="header-anchor" href="#中国省级行政区划表" aria-label="Permalink to &quot;中国省级行政区划表&quot;">​</a></h2><p><img src="https://www.dljs.net/uploads/allimg/map/china/113T3H45-0.jpg" alt=""></p><table tabindex="0"><thead><tr><th>类型</th><th>名称</th><th>人口（万）</th><th>面积（万平方公里）</th><th>首府/政府驻地</th><th>备注</th></tr></thead><tbody><tr><td><strong>省</strong></td><td>广东省</td><td>12,601</td><td>17.98</td><td>广州</td><td>经济第一大省，珠三角核心区</td></tr><tr><td></td><td>山东省</td><td>10,152</td><td>15.79</td><td>济南</td><td>农业大省，儒家文化发源地</td></tr><tr><td></td><td>河南省</td><td>9,936</td><td>16.70</td><td>郑州</td><td>中原文化中心，粮食产量全国第二</td></tr><tr><td></td><td>江苏省</td><td>8,474</td><td>10.72</td><td>南京</td><td>人均GDP最高省份，长三角经济带</td></tr><tr><td></td><td>四川省</td><td>8,367</td><td>48.60</td><td>成都</td><td>面积最大省份（含直辖市/自治区外）</td></tr><tr><td></td><td>河北省</td><td>7,461</td><td>18.88</td><td>石家庄</td><td>环京津特殊区位</td></tr><tr><td></td><td>湖南省</td><td>6,644</td><td>21.18</td><td>长沙</td><td>杂交水稻发源地</td></tr><tr><td></td><td>浙江省</td><td>6,457</td><td>10.55</td><td>杭州</td><td>数字经济先行区</td></tr><tr><td></td><td>安徽省</td><td>6,103</td><td>14.01</td><td>合肥</td><td>长三角新兴增长极</td></tr><tr><td></td><td>湖北省</td><td>5,775</td><td>18.59</td><td>武汉</td><td>九省通衢，中部交通枢纽</td></tr><tr><td></td><td>福建省</td><td>4,157</td><td>12.40</td><td>福州</td><td>民营经济发达，侨乡集中地</td></tr><tr><td></td><td>江西省</td><td>4,517</td><td>16.69</td><td>南昌</td><td>革命老区，景德镇陶瓷文化</td></tr><tr><td></td><td>陕西省</td><td>3,953</td><td>20.56</td><td>西安</td><td>十三朝古都，丝绸之路起点</td></tr><tr><td></td><td>辽宁省</td><td>4,259</td><td>14.80</td><td>沈阳</td><td>东北经济中心，重工业基地</td></tr><tr><td></td><td>云南省</td><td>4,720</td><td>39.41</td><td>昆明</td><td>少数民族种类最多（25个世居民族）</td></tr><tr><td></td><td>黑龙江省</td><td>3,125</td><td>47.30</td><td>哈尔滨</td><td>中国最北省份，冰雪旅游胜地</td></tr><tr><td></td><td>贵州省</td><td>3,856</td><td>17.62</td><td>贵阳</td><td>大数据产业中心，茅台酒原产地</td></tr><tr><td></td><td>山西省</td><td>3,491</td><td>15.67</td><td>太原</td><td>煤炭资源大省，晋商文化发祥地</td></tr><tr><td></td><td>吉林省</td><td>2,407</td><td>18.74</td><td>长春</td><td>汽车工业基地，长白山所在地</td></tr><tr><td></td><td>甘肃省</td><td>2,502</td><td>42.58</td><td>兰州</td><td>河西走廊核心区，莫高窟所在地</td></tr><tr><td></td><td>海南省</td><td>1,008</td><td>3.54</td><td>海口</td><td>国际旅游岛，自由贸易试验区</td></tr><tr><td></td><td>青海省</td><td>592</td><td>72.23</td><td>西宁</td><td>三江源国家公园，青藏高原门户</td></tr><tr><td></td><td>台湾省(注)</td><td>2,356</td><td>3.60</td><td>台北</td><td>实际管辖情况详见中国政府官方说明</td></tr><tr><td><strong>直辖市</strong></td><td>重庆市</td><td>3,205</td><td>8.24</td><td>渝中区</td><td>面积最大的直辖市</td></tr><tr><td></td><td>上海市</td><td>2,487</td><td>0.63</td><td>黄浦区</td><td>中国经济中心</td></tr><tr><td></td><td>北京市</td><td>2,189</td><td>1.64</td><td>通州区</td><td>首都，政治文化中心</td></tr><tr><td></td><td>天津市</td><td>1,386</td><td>1.19</td><td>河西区</td><td>北方重要港口城市</td></tr><tr><td><strong>自治区</strong></td><td>广西壮族自治区</td><td>5,019</td><td>23.76</td><td>南宁</td><td>少数民族人口最多（壮族占32.5%）</td></tr><tr><td></td><td>新疆维吾尔自治区</td><td>2,585</td><td>166.49</td><td>乌鲁木齐</td><td>面积最大省级行政区</td></tr><tr><td></td><td>内蒙古自治区</td><td>2,401</td><td>118.30</td><td>呼和浩特</td><td>横跨东北/华北/西北</td></tr><tr><td></td><td>宁夏回族自治区</td><td>720</td><td>6.64</td><td>银川</td><td>黄河流经的塞上江南</td></tr><tr><td></td><td>西藏自治区</td><td>365</td><td>120.28</td><td>拉萨</td><td>平均海拔4000米以上的高原地区</td></tr><tr><td><strong>特别行政区</strong></td><td>香港特别行政区</td><td>747</td><td>0.11</td><td>香港岛</td><td>国际金融中心，实行&quot;一国两制&quot;</td></tr><tr><td></td><td>澳门特别行政区</td><td>68</td><td>0.0033</td><td>澳门半岛</td><td>世界人口密度最高地区</td></tr></tbody></table><h3 id="重要说明" tabindex="-1">重要说明 <a class="header-anchor" href="#重要说明" aria-label="Permalink to &quot;重要说明&quot;">​</a></h3><ol><li><strong>省级单位总数</strong>：23省 + 5自治区 + 4直辖市 + 2特别行政区 = 34个省级行政区；</li><li><strong>台湾省标注</strong>：人口和面积为估算值（2023年），中国政府坚持一个中国原则；</li><li><strong>数据时效</strong>：人口数据为2020年普查结果（港澳台除外），面积含陆地及内水；</li><li><strong>特殊政策地区</strong>： <ul><li>海南省：经济特区 + 自由贸易港</li><li>新疆：丝绸之路经济带核心区</li><li>西藏：国家生态安全屏障</li></ul></li></ol>',12),a=[s];function e(l,g,i,h,c,_){return r(),d("div",null,a)}const p=t(n,[["render",e]]);export{u as __pageData,p as default};
